import sqlite3
from pathlib import Path

CLAIM_ID = "clm_7f3c1e9a"


def _db(ws):
    ws = Path(ws)
    candidates = [ws.parent / "system" / "vpi_claims_adjudication" / "state.db", Path("system/vpi_claims_adjudication/state.db")]
    for path in candidates:
        if path.exists():
            return path
    raise FileNotFoundError("VPI Claims Adjudication Platform database not found")


def _rows(con, table, where, params=()):
    return [dict(row) for row in con.execute(f"SELECT * FROM {table} WHERE {where}", params)]


def _normalized_id(value):
    return "".join(ch for ch in (value or "").casefold() if ch.isalnum())


def _is_sarah_chen(value):
    return _normalized_id(value) in {"sarahchen", "usersarahchen", "usrclaimsspecialist031"}


def _has_recalculation_language(rationale):
    return any(term in rationale for term in ("recalculate", "recalculation", "recomputed", "reperformance", "reconciliation"))


def _has_schedule_evidence(evidence, code, column, amount):
    aliases = (
        f"allow_0476_{code}_{column.lower()}",
        f"allow_2013_{code}_{column.lower()}",
        f"{code}_{column}({amount})",
        f"{code}/{column}",
    )
    return any(alias.casefold() in evidence for alias in aliases)


def _has_active_deductible_evidence(evidence):
    return ("pe_vpi_2025_ded_0673" in evidence
            or "deductible_term_active:31827_remaining" in evidence
            or ("term_vpi_ca_25_784316_2025" in evidence and "31827" in evidence))


def _has_identity_language(rationale):
    return ("identity" in rationale
            or ("patient" in rationale and ("pet" in rationale or "provider" in rationale)))


def check_new_review(ws):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    rows = _rows(con, "claim_reviews", "claim_id = ?", (CLAIM_ID,))
    con.close()
    matching = []
    for row in rows:
        rationale = (row.get("rationale") or "").casefold()
        evidence = (row.get("evidence_reference") or "").casefold()
        if (
            _is_sarah_chen(row.get("reviewer_id"))
            and row.get("reviewer_role") == "claims_calculation_specialist"
            and row.get("decision") == "approved"
            and row.get("valid_decision") == 1
            and "independent" in rationale
            and _has_recalculation_language(rationale)
            and _has_identity_language(rationale)
            and "display" in rationale
            and "inv_vca_2025_0912_8471" in evidence
            and _has_schedule_evidence(evidence, "1220", "A", "62000")
            and _has_schedule_evidence(evidence, "1221", "B", "150000")
            and _has_active_deductible_evidence(evidence)
        ):
            matching.append(row)
    if len(matching) != 1:
        return {"score": 0, "detail": f"expected one matching new Sarah Chen review, found {len(matching)}"}
    if matching[0]["review_id"] in {"review_0476_specialist", "review_0476_vet"}:
        return {"score": 0, "detail": "matching row is an existing review, not a new review"}
    return {"score": 1, "detail": f"new approved calculation review recorded as {matching[0]['review_id']}"}


